:root {
  --primary: #24685c;
  --secondary: #194f46;
  --accent: #e5eee7;
  --dark: #183e37;
  --page-bg: #f8f5ee;
  --text: #293d37;
  --bs-body-font-family: 'Manrope', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --bs-body-bg: var(--page-bg);
  --bs-body-color: var(--text);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background-color: var(--page-bg);
  color: var(--text);
  font-family: var(--bs-body-font-family);
  line-height: 1.7;
}
h1, h2, h3, h6, .navbar-brand, .display-heading {
  font-family: inherit;
  line-height: 1.2;
  overflow-wrap: anywhere;
}
h1, h2 { letter-spacing: -0.035em; }
p { overflow-wrap: anywhere; }
section { scroll-margin-top: 1.5rem; }
section.py-5 { padding-block: clamp(3rem, 6vw, 5.5rem) !important; }
.row > * { min-width: 0; }
.navbar { background-color: var(--dark); padding-block: 1rem; }
.navbar > .container { gap: 0.75rem 1.5rem; }
.navbar-brand {
  color: #fff;
  margin-right: 0;
  white-space: normal;
  max-width: calc(100% - 5rem);
  font-size: clamp(1.125rem, 3vw, 1.5rem) !important;
