:root {
  --primary: #b85436;
  --primary-hover: #9c4125;
  --secondary: #944627;
  --accent: #f8ece4;
  --accent-light: #fbf4ee;
  --dark: #2f201c;
  --darker: #201512;
  --bg-app: #faf6f0;
  --bg-surface: #ffffff;
  --bg-services: #f2ebe1;
  --text-main: #2d2624;
  --text-muted: #6e6460;
  --card-border: rgba(184, 84, 54, 0.12);
  --shadow-sm: 0 4px 16px rgba(47, 32, 28, 0.06);
  --shadow-md: 0 10px 28px rgba(47, 32, 28, 0.1);
  --shadow-lg: 0 16px 36px rgba(184, 84, 54, 0.15);
  --font-headings: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: hidden;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-app);
  line-height: 1.65;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Typography */
h1, h2, h3, h4, h5, h6,
.navbar-brand,
.display-heading,
.section-title,
.footer-brand {
  font-family: var(--font-headings);
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--dark);
  overflow-wrap: break-word;
}

p, ul, ol {
  overflow-wrap: break-word;
}

section[id] {
  scroll-margin-top: 76px;
}

/* Navbar */
.navbar {
  background-color: var(--dark) !important;
  padding: 0.9rem 0;
  box-shadow: 0 2px 14px rgba(32, 21, 18, 0.22);
  position: sticky;
  top: 0;
  z-index: 1030;
}

.navbar-brand {
  color: #ffffff !important;
  font-size: clamp(1.25rem, 3.2vw, 1.55rem);
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: opacity 0.2s ease;
}

.navbar-brand:hover {
  opacity: 0.9;
}

.navbar .nav-link {
  color: rgba(255, 255, 255, 0.85) !important;
  font-weight: 500;
  font-size: 0.96rem;
  padding: 0.5rem 1rem !important;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.navbar .nav-link:hover,
.navbar .nav-link:focus {
  color: #ffffff !important;
  background-color: rgba(255, 255, 255, 0.12);
}

.navbar-toggler {
  border: 1px solid rgba(255, 255, 255, 0.25);
  padding: 0.45rem 0.7rem;
  border-radius: 6px;
}

.navbar-toggler:focus {
  box-shadow: 0 0 0 0.2rem rgba(184, 84, 54, 0.35);
}

@media (max-width: 991.98px) {
  .navbar-collapse {
    background-color: var(--darker);
    margin-top: 0.75rem;
    padding: 1rem 0.75rem;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.08);
  }

  .navbar-nav .nav-item {
    margin-bottom: 0.3rem;
  }

  .navbar .nav-link {
    padding: 0.6rem 0.85rem !important;
  }
}

/* Hero Section */
.hero-image-full {
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  position: relative;
  min-height: 480px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-overlay {
  background: linear-gradient(180deg, rgba(32, 21, 18, 0.75) 0%, rgba(32, 21, 18, 0.58) 100%);
  width: 100%;
  min-height: 480px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.display-heading {
  font-size: clamp(2.3rem, 5.5vw, 3.8rem);
  font-weight: 700;
  line-height: 1.18;
  letter-spacing: -0.01em;
  color: #ffffff;
  margin-bottom: 1.1rem;
}

.hero-overlay .lead {
  font-size: clamp(1.1rem, 2.5vw, 1.35rem);
  color: rgba(255, 255, 255, 0.9);
  max-width: 620px;
  margin: 0 auto 1.5rem auto;
}

/* Buttons */
.btn-brand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: var(--primary);
  border: 1px solid var(--primary);
  color: #ffffff;
  font-weight: 600;
  font-size: 1rem;
  padding: 0.8rem 1.8rem;
  border-radius: 8px;
  text-decoration: none;
  transition: all 0.25s ease;
  box-shadow: 0 4px 14px rgba(184, 84, 54, 0.28);
}

.btn-brand:hover,
.btn-brand:focus {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-brand:active {
  transform: translateY(0);
}

/* About Section */
.section-about {
  background-color: var(--bg-app);
  position: relative;
}

.section-title {
  font-size: clamp(1.85rem, 3.8vw, 2.5rem);
  line-height: 1.25;
  color: var(--dark);
  margin-bottom: 1.2rem;
}

.about-img {
  width: 100%;
  max-height: 420px;
  object-fit: cover;
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  border: 1px solid rgba(47, 32, 28, 0.08);
}

.feature-list {
  margin-top: 1.5rem;
}

.feature-item {
  display: flex;
  align-items: center;
  margin-bottom: 0.85rem;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-main);
}

.check-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background-color: var(--accent);
  color: var(--primary);
  font-weight: 700;
  font-size: 0.85rem;
  margin-right: 0.85rem;
  flex-shrink: 0;
}

/* Services Section */
.section-services {
  background-color: var(--bg-services);
  position: relative;
}

.card-service {
  background-color: var(--bg-surface);
  border: 1px solid var(--card-border);
  border-top: 4px solid var(--primary);
  border-radius: 12px;
  height: 100%;
  min-height: 180px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  box-shadow: var(--shadow-sm);
}

.card-service:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
}

.card-service h6 {
  font-family: var(--font-headings);
  color: var(--dark);
  font-size: 1.15rem;
  font-weight: 700;
  min-height: 2.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.6rem;
  width: 100%;
}

.card-service p {
  color: var(--text-muted);
  line-height: 1.55;
  margin: 0;
  flex-grow: 1;
  display: flex;
  align-items: center;
}

/* Testimonial Section */
.section-testimonial {
  background-color: var(--bg-app);
  position: relative;
}

.testimonial-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
}

.quote-mark {
  font-family: var(--font-headings);
  font-size: 3.5rem;
  line-height: 1;
  color: var(--primary);
  opacity: 0.4;
  margin-bottom: -0.5rem;
}

.testimonial-quote {
  font-family: var(--font-headings);
  font-size: clamp(1.2rem, 2.6vw, 1.5rem);
  font-style: italic;
  line-height: 1.6;
  color: var(--dark);
  margin-bottom: 1.25rem;
}

.testimonial-author {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* Contact Section */
.hero-dark {
  background-color: var(--dark);
  color: #ffffff;
  position: relative;
}

.hero-dark h2 {
  color: #ffffff;
}

.hero-dark .lead-text {
  color: rgba(255, 255, 255, 0.8);
  font-size: 1.15rem;
}

/* Footer */
footer {
  background-color: var(--darker);
  color: #ffffff;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-brand {
  color: #ffffff;
  font-size: 1.25rem;
  letter-spacing: 0.02em;
}

.footer-copy {
  color: rgba(255, 255, 255, 0.65);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

